    std::unordered_map<S,V> notes;std::unordered_map<S,Entry> noteOrigins;V canonicalNoteHeader;V nh;std::map<S,int> ni;U invalidNotes=0;for(size_t nf=0;nf<noteFiles.size();++nf){auto&file=noteFiles[nf];Reader nr(file);nr.next(nh,off);if(nf&&nh!=canonicalNoteHeader)throw std::runtime_error("Notes shard schemas differ");canonicalNoteHeader=nh;ni.clear();for(size_t i=0;i<nh.size();++i)ni[nh[i]]=i;while(nr.next(v,off)){S id=trim(v.at(ni.at("noteId")));if(!validid(id)){++invalidNotes;continue;}V fields{v.at(ni.at("createdAtMillis")),ni.count("classification")?v.at(ni.at("classification")):""};auto it=notes.find(id);if(it!=notes.end()){if(it->second!=fields||at(noteOrigins.at(id),noteFiles)!=v)throw std::runtime_error("Conflicting Notes IDs");}else noteOrigins[id]=Entry{0,0,0,off,uint32_t(nf),0};notes[id]=fields;}}
